<script setup lang="ts">
import {t,formatAmount,formatDate,formatBusinessStatus} from '@kuaixie/i18n';
import {useShopOrders,shopStockStateKey} from '@kuaixie/ui/useShopOrders';
import {api} from '../api/client';
const p=useShopOrders(api);
</script>
<template><view class="shop-orders-mobile"><view class="op-card-title">{{t('shopOrders.title')}}</view><view class="v15-notice">{{t('shopOrders.snapshotNotice')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><button :disabled="p.busy.value" @click="p.load()">{{t('common.retry')}}</button><view v-if="p.busy.value" class="op-empty">{{t('account.loading')}}</view><view v-if="!p.busy.value&&!p.error.value&&!p.rows.value.length" class="op-empty">{{t('shopOrders.empty')}}</view><view v-for="order in p.rows.value" :key="order.id" class="op-card"><view class="op-card-title">{{order.order_no||order.id}} · {{order.item_name}}</view><view>{{formatBusinessStatus(order.status)}} · {{formatDate(order.created_at)}}</view><view class="op-row"><text>{{t('shopOrders.quantity')}}</text><text>{{order.quantity}}</text></view><view class="op-row"><text>{{t('shopOrders.goods')}}</text><text>{{formatAmount(order.goods_amount,order.currency)}}</text></view><view class="op-row"><text>{{t('shopOrders.serviceFee')}}</text><text>{{formatAmount(order.service_fee,order.currency)}}</text></view><view class="op-row"><text>{{t('shopOrders.stock')}}</text><text>{{t(shopStockStateKey(order.stock_state))}}</text></view><button @click="uni.navigateTo({url:'/pages/order-detail/index?id='+encodeURIComponent(order.id)})">{{t('account.details')}}</button></view><button v-if="p.more.value" :disabled="p.busy.value" @click="p.load(true)">{{t('account.more')}}</button></view></template>
